package server_test

import (
	"bytes"
	"compress/gzip"
	"io"
	"os"
	"path/filepath"
	"testing"

	apiv1 "github.com/uw-syfi/vibesys/gateway/gen/vibesys/api/v1"
	storev1 "github.com/uw-syfi/vibesys/gateway/gen/vibesys/store/v1"
	"github.com/uw-syfi/vibesys/gateway/internal/runlog"
	"google.golang.org/protobuf/proto"
)

// These files are generated by the Python FileRunLogWriter, rather than a Go
// imitation of the writer's framing, publication order or checkpoint offsets.
func TestPythonWriterSkeletonFixtures(t *testing.T) {
	for _, name := range []string{"core", "epochs", "converted"} {
		t.Run(name, func(t *testing.T) {
			f := start(t)
			source := filepath.Join("../../../proto/testdata/skeleton", name)
			if name == "converted" {
				source = "../../../proto/testdata/conversion"
			}
			for _, filename := range []string{"run.log", "run.head"} {
				path := filepath.Join(source, filename)
				if name == "converted" && filename == "run.log" {
					path += ".gz"
				}
				payload, err := os.ReadFile(path)
				if err != nil {
					t.Fatal(err)
				}
				if name == "converted" && filename == "run.log" {
					compressed, err := gzip.NewReader(bytes.NewReader(payload))
					if err != nil {
						t.Fatal(err)
					}
					payload, err = io.ReadAll(compressed)
					if err != nil {
						t.Fatal(err)
					}
					if err := compressed.Close(); err != nil {
						t.Fatal(err)
					}
					if len(payload) <= 1<<20 {
						t.Fatal("converted log must exceed Skeleton replay budget")
					}
				}
				write(t, filepath.Join(f.run, filename), false, payload)
			}
			entries, err := os.ReadDir(filepath.Join(source, "keyframes"))
			if err != nil {
				t.Fatal(err)
			}
			if err := os.Mkdir(filepath.Join(f.run, "keyframes"), 0700); err != nil {
				t.Fatal(err)
			}
			for _, entry := range entries {
				payload, err := os.ReadFile(filepath.Join(source, "keyframes", entry.Name()))
				if err != nil {
					t.Fatal(err)
				}
				write(t, filepath.Join(f.run, "keyframes", entry.Name()), false, payload)
			}
			expected, err := os.ReadFile(filepath.Join(source, "expected.pb"))
			if err != nil {
				t.Fatal(err)
			}
			var keyframe storev1.Keyframe
			if err := proto.Unmarshal(expected, &keyframe); err != nil {
				t.Fatal(err)
			}
			got, err := client(t, f, false).Skeleton(f.ctx, &apiv1.SkeletonRequest{RunId: "run-1"})
			if err != nil {
				t.Fatal(err)
			}
			if name == "converted" {
				pinWireGolden(t, got)
			}
			if _, err := runlog.UpgradeSkeleton(&keyframe); err != nil {
				t.Fatal(err)
			}
			actual := restored(t, got, nil)
			if !proto.Equal(actual, &keyframe) || got.CommittedSeq != keyframe.ThroughSeq || !got.Complete || len(got.Records) != 0 {
				t.Fatalf("Python checkpoint did not round trip: %v", got)
			}

		})
	}
}

// The TypeScript reader decodes this exact reply (clients/libs/run-skeleton
// descriptors.test.ts), so the two languages agree on what the hash names.
// Set VIBESYS_UPDATE_GOLDEN=1 to rewrite it after a deliberate wire change.
func pinWireGolden(t *testing.T, reply *apiv1.SkeletonResponse) {
	t.Helper()
	path := "../../../proto/testdata/skeleton-wire/converted.response.pb.gz"
	encoded, err := proto.MarshalOptions{Deterministic: true}.Marshal(reply)
	if err != nil {
		t.Fatal(err)
	}
	var packed bytes.Buffer
	writer, err := gzip.NewWriterLevel(&packed, gzip.BestCompression)
	if err != nil {
		t.Fatal(err)
	}
	if _, err := writer.Write(encoded); err != nil {
		t.Fatal(err)
	}
	if err := writer.Close(); err != nil {
		t.Fatal(err)
	}
	if os.Getenv("VIBESYS_UPDATE_GOLDEN") != "" {
		if err := os.MkdirAll(filepath.Dir(path), 0755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(path, packed.Bytes(), 0644); err != nil {
			t.Fatal(err)
		}
	}
	golden, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	reader, err := gzip.NewReader(bytes.NewReader(golden))
	if err != nil {
		t.Fatal(err)
	}
	want, err := io.ReadAll(reader)
	if err != nil {
		t.Fatal(err)
	}
	if !bytes.Equal(want, encoded) {
		t.Fatalf("Skeleton reply differs from %s; rerun with VIBESYS_UPDATE_GOLDEN=1 if intended", path)
	}
}
